/**
 * Creates Persian (fa) content pages: bank-runs, wallets, buy, lightning,
 * stickers, postcards, signs, flyers, get-involved.
 * Reads English sources and writes translated versions.
 */
const fs = require('fs');
const path = require('path');

const i18nDir = path.join(__dirname, '..', '..', 'i18n');
const lang = 'fa';
const today = '2026-04-11';

function translateFile(enFileName, faFileName, translations) {
	const enData = JSON.parse(fs.readFileSync(path.join(i18nDir, 'en', enFileName), 'utf8'));
	const output = { "@metadata": { "authors": ["Satoshi"], "last-updated": today, "locale": lang } };
	Object.keys(enData).forEach(key => {
		if (key === '@metadata') return;
		output[key] = translations[key] || enData[key];
	});
	const filePath = path.join(i18nDir, lang, faFileName);
	fs.mkdirSync(path.dirname(filePath), { recursive: true });
	fs.writeFileSync(filePath, JSON.stringify(output, null, '\t') + '\n', 'utf8');
	console.log(`CREATED: ${filePath}`);
}

// bank-runs
translateFile('bank-runs_en.json', `bank-runs_${lang}.json`, {
	"bitcoin_doesnt_have_bank_runs": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0647\u062C\u0648\u0645 \u0628\u0627\u0646\u06A9\u06CC \u0646\u062F\u0627\u0631\u062F",
	"bank_runs_header": "\u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0647\u062C\u0648\u0645 \u0628\u0627\u0646\u06A9\u06CC \u0646\u062F\u0627\u0631\u062F", "bank_runs_header_2": "\u0627\u0645\u0627 \u0628\u0627\u0646\u06A9 \u0634\u0645\u0627 \u0634\u0627\u06CC\u062F \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u062F",
	"bank_runs_what": "\u0647\u062C\u0648\u0645 \u0628\u0627\u0646\u06A9\u06CC \u0686\u06CC\u0633\u062A\u061F", "bank_runs_what_content_1": "\u0647\u062C\u0648\u0645 \u0628\u0627\u0646\u06A9\u06CC \u0632\u0645\u0627\u0646\u06CC \u0627\u062A\u0641\u0627\u0642 \u0645\u06CC\u200C\u0627\u0641\u062A\u062F \u06A9\u0647 \u062A\u0639\u062F\u0627\u062F \u0632\u06CC\u0627\u062F\u06CC \u0627\u0632 \u0645\u0631\u062F\u0645 \u0647\u0645\u200C\u0632\u0645\u0627\u0646 \u0633\u0639\u06CC \u0645\u06CC\u200C\u06A9\u0646\u0646\u062F \u067E\u0648\u0644\u0634\u0627\u0646 \u0631\u0627 \u0627\u0632 \u0628\u0627\u0646\u06A9 \u0628\u0631\u062F\u0627\u0634\u062A \u06A9\u0646\u0646\u062F.", "bank_runs_what_content_2": "\u0627\u06AF\u0631 \u0628\u0627\u0646\u06A9\u200C\u0647\u0627 \u067E\u0648\u0644 \u06A9\u0627\u0641\u06CC \u0628\u0631\u0627\u06CC \u0628\u0631\u062F\u0627\u0634\u062A\u200C\u0647\u0627 \u0646\u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u0646\u062F\u060C \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u0646\u062F \u06A9\u0627\u0645\u0644\u0627\u064B \u0633\u0642\u0648\u0637 \u06A9\u0646\u0646\u062F.",
	"bank_runs_how": "\u0647\u062C\u0648\u0645 \u0628\u0627\u0646\u06A9\u06CC \u0686\u06AF\u0648\u0646\u0647 \u0627\u062A\u0641\u0627\u0642 \u0645\u06CC\u200C\u0627\u0641\u062A\u062F\u061F", "bank_runs_how_content_1": "\u0633\u06CC\u0633\u062A\u0645 \u0628\u0627\u0646\u06A9\u06CC \u0645\u0627 \u00AB\u0630\u062E\u06CC\u0631\u0647 \u06A9\u0633\u0631\u06CC\u00BB \u0627\u0633\u062A\u060C \u0628\u0647 \u0627\u06CC\u0646 \u0645\u0639\u0646\u06CC \u06A9\u0647 \u0628\u0627\u0646\u06A9\u200C\u0647\u0627 \u0641\u0642\u0637 \u067E\u0648\u0644 \u0634\u0645\u0627 \u0631\u0627 \u062F\u0631 \u06AF\u0627\u0648\u0635\u0646\u062F\u0648\u0642 \u0646\u06AF\u0647 \u0646\u0645\u06CC\u200C\u062F\u0627\u0631\u0646\u062F.", "bank_runs_how_content_2": "\u062F\u0631 \u0639\u0648\u0636\u060C \u0628\u0627\u0646\u06A9 \u067E\u0648\u0644 \u0634\u0645\u0627 \u0631\u0627 \u0648\u0627\u0645 \u0645\u06CC\u200C\u062F\u0647\u062F \u06CC\u0627 \u0633\u0631\u0645\u0627\u06CC\u0647\u200C\u06AF\u0630\u0627\u0631\u06CC \u0645\u06CC\u200C\u06A9\u0646\u062F.", "bank_runs_how_content_3": "\u067E\u0633 \u0627\u06AF\u0631 \u0628\u062E\u0648\u0627\u0647\u06CC\u062F \u067E\u0648\u0644\u062A\u0627\u0646 \u0631\u0627 \u0628\u0631\u062F\u0627\u0634\u062A \u06A9\u0646\u06CC\u062F \u0628\u0639\u062F \u0627\u0632 \u0627\u06CC\u0646\u06A9\u0647 \u0628\u0627\u0646\u06A9 \u0622\u0646 \u0631\u0627 \u0648\u0627\u0645 \u062F\u0627\u062F\u0647 \u0686\u0647\u061F", "bank_runs_how_content_4": "\u0627\u06AF\u0631 \u0641\u0642\u0637 \u0634\u0645\u0627 \u0628\u062E\u0648\u0627\u0647\u06CC\u062F \u0628\u0631\u062F\u0627\u0634\u062A \u06A9\u0646\u06CC\u062F \u0645\u0634\u06A9\u0644\u06CC \u0646\u06CC\u0633\u062A. \u0627\u0645\u0627 \u0648\u0642\u062A\u06CC \u062A\u0639\u062F\u0627\u062F \u0632\u06CC\u0627\u062F\u06CC \u0647\u0645\u200C\u0632\u0645\u0627\u0646 \u0628\u062E\u0648\u0627\u0647\u0646\u062F \u0628\u0631\u062F\u0627\u0634\u062A \u06A9\u0646\u0646\u062F \u0686\u0647\u061F", "bank_runs_how_content_5": "\u0628\u0633\u06CC\u0627\u0631\u06CC \u0627\u0632 \u0645\u0631\u062F\u0645 \u062F\u0631 \u0622\u0645\u0631\u06CC\u06A9\u0627 \u0648\u0642\u062A\u06CC \u062F\u0631 \u0645\u0627\u0631\u0633 \u06F2\u06F0\u06F2\u06F3 \u0647\u062C\u0648\u0645 \u0628\u0647 \u0628\u0627\u0646\u06A9 \u0633\u06CC\u0644\u06CC\u06A9\u0648\u0646 \u0648\u0644\u06CC \u0634\u062F \u0641\u0647\u0645\u06CC\u062F\u0646\u062F.", "bank_runs_how_content_6": "\u0628\u0627\u0646\u06A9 \u067E\u0648\u0644 \u0645\u0634\u062A\u0631\u06CC\u0627\u0646\u0634 \u0631\u0627 \u062F\u0631 \u0627\u0648\u0631\u0627\u0642 \u0642\u0631\u0636\u0647 \u062F\u0648\u0644\u062A\u06CC \u0633\u0631\u0645\u0627\u06CC\u0647\u200C\u06AF\u0630\u0627\u0631\u06CC \u06A9\u0631\u062F\u0647 \u0628\u0648\u062F \u06A9\u0647 \u062A\u0627 \u06F3\u06F0 \u0633\u0627\u0644 \u0642\u0641\u0644 \u0628\u0648\u062F\u0646\u062F.", "bank_runs_how_content_7": "\u0628\u0627 \u0627\u0637\u0644\u0627\u0639 \u0628\u06CC\u0634\u062A\u0631 \u0645\u0631\u062F\u0645\u060C \u0645\u0634\u06A9\u0644 \u0628\u062F\u062A\u0631 \u0634\u062F. \u062F\u0631\u062E\u0648\u0627\u0633\u062A\u200C\u0647\u0627\u06CC \u0628\u0631\u062F\u0627\u0634\u062A \u0628\u06CC\u0634\u062A\u0631\u06CC \u0622\u0645\u062F \u0627\u0645\u0627 \u0628\u0633\u06CC\u0627\u0631\u06CC \u067E\u0631\u062F\u0627\u0632\u0634 \u0646\u0634\u062F\u0646\u062F.", "bank_runs_how_content_8": "FDIC \u0648\u0627\u0631\u062F \u0634\u062F \u0648 \u0645\u0648\u0627\u0641\u0642\u062A \u06A9\u0631\u062F \u0633\u067E\u0631\u062F\u0647\u200C\u06AF\u0630\u0627\u0631\u0627\u0646 \u0631\u0627 \u06A9\u0627\u0645\u0644 \u06A9\u0646\u062F. \u0645\u0634\u06A9\u0644 \u062D\u0644 \u0634\u062F\u061F \u0646\u0647 \u062F\u0642\u06CC\u0642\u0627\u064B...",
	"bank_runs_fdic": "\u0622\u06CC\u0627 \u0628\u06CC\u0645\u0647 FDIC \u0627\u0632 \u067E\u0648\u0644 \u0645\u0646 \u0645\u062D\u0627\u0641\u0638\u062A \u0645\u06CC\u200C\u06A9\u0646\u062F\u061F", "bank_runs_fdic_content_1": "\u0628\u06CC\u0645\u0647 FDIC \u0628\u0631\u0627\u06CC \u0645\u062D\u0627\u0641\u0638\u062A \u0627\u0632 \u0633\u067E\u0631\u062F\u0647\u200C\u06AF\u0630\u0627\u0631\u0627\u0646 \u0628\u0627\u0646\u06A9 \u062F\u0631 \u0635\u0648\u0631\u062A \u0648\u0631\u0634\u06A9\u0633\u062A\u06AF\u06CC \u0637\u0631\u0627\u062D\u06CC \u0634\u062F\u0647. \u0633\u067E\u0631\u062F\u0647\u200C\u0647\u0627 \u062A\u0627 \u06F2\u06F5\u06F0\u066C\u06F0\u06F0\u06F0 \u062F\u0644\u0627\u0631 \u0628\u06CC\u0645\u0647 \u0647\u0633\u062A\u0646\u062F.", "bank_runs_fdic_content_2": "\u0646\u0647 \u062F\u0642\u06CC\u0642\u0627\u064B. \u0627\u06AF\u0631 \u0628\u0627\u0646\u06A9\u06CC \u0648\u0631\u0634\u06A9\u0633\u062A \u06A9\u0646\u062F\u060C FDIC \u067E\u0648\u0644 \u0631\u0627 \u0627\u0632 \u06A9\u062C\u0627 \u0645\u06CC\u200C\u0622\u0648\u0631\u062F\u061F \u0622\u0646\u0647\u0627 \u06CC\u06A9 \u0635\u0646\u062F\u0648\u0642 \u0628\u06CC\u0645\u0647 \u0628\u0627 \u06F1\u06F2\u06F5 \u0645\u06CC\u0644\u06CC\u0627\u0631\u062F \u062F\u0644\u0627\u0631 \u062F\u0627\u0631\u0646\u062F.", "bank_runs_fdic_content_3": "\u0627\u06CC\u0646 \u062A\u0627 \u0648\u0642\u062A\u06CC \u0628\u0627 \u0645\u0642\u062F\u0627\u0631 \u0633\u067E\u0631\u062F\u0647\u200C\u0647\u0627\u06CC\u06CC \u06A9\u0647 \u0628\u06CC\u0645\u0647 \u0645\u06CC\u200C\u06A9\u0646\u0646\u062F \u0645\u0642\u0627\u06CC\u0633\u0647 \u06A9\u0646\u06CC\u062F \u0632\u06CC\u0627\u062F \u0628\u0647 \u0646\u0638\u0631 \u0645\u06CC\u200C\u0631\u0633\u062F: \u062A\u0642\u0631\u06CC\u0628\u0627\u064B \u06F1\u06F0 \u062A\u0631\u06CC\u0644\u06CC\u0648\u0646 \u062F\u0644\u0627\u0631.", "bank_runs_fdic_content_4": "FDIC \u062F\u0631 \u0648\u0628\u200C\u0633\u0627\u06CC\u062A\u0634 \u0646\u0634\u0627\u0646 \u0645\u06CC\u200C\u062F\u0647\u062F \u06A9\u0647 \u0641\u0642\u0637 \u06A9\u0645\u06CC \u0628\u06CC\u0634 \u0627\u0632 \u06F1\u066A \u0633\u067E\u0631\u062F\u0647\u200C\u0647\u0627 \u0631\u0627 \u067E\u0648\u0634\u0634 \u0645\u06CC\u200C\u062F\u0647\u062F.", "bank_runs_fdic_content_5": "\u062F\u0631 \u0635\u0648\u0631\u062A \u0648\u0631\u0634\u06A9\u0633\u062A\u06AF\u06CC \u0628\u0627\u0646\u06A9\u06CC \u06A9\u0647 \u0627\u0632 \u0635\u0646\u062F\u0648\u0642 \u0628\u06CC\u0645\u0647 \u0641\u0631\u0627\u062A\u0631 \u0628\u0631\u0648\u062F\u060C \u0627\u062D\u062A\u0645\u0627\u0644\u0627\u064B \u062F\u0648\u0644\u062A \u067E\u0648\u0644 \u0686\u0627\u067E \u0645\u06CC\u200C\u06A9\u0646\u062F.", "bank_runs_fdic_content_6": "\u0627\u0645\u0627 \u0686\u0627\u067E \u067E\u0648\u0644 \u0628\u0627\u0639\u062B \u062A\u0648\u0631\u0645 \u0645\u06CC\u200C\u0634\u0648\u062F\u060C \u067E\u0633 \u0631\u0627\u0647\u200C\u062D\u0644 \u062E\u0648\u0628\u06CC \u0646\u06CC\u0633\u062A.",
	"bank_runs_safe": "\u0622\u06CC\u0627 \u0628\u0627\u0646\u06A9\u200C\u0647\u0627\u06CC\u06CC \u0647\u0633\u062A\u0646\u062F \u06A9\u0647 \u0627\u0632 \u0630\u062E\u06CC\u0631\u0647 \u06A9\u0633\u0631\u06CC \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0646\u06A9\u0646\u0646\u062F\u061F", "bank_runs_safe_content_1": "\u0628\u0631\u062E\u06CC \u0628\u0627\u0646\u06A9\u200C\u0647\u0627 \u0633\u0639\u06CC \u06A9\u0631\u062F\u0647\u200C\u0627\u0646\u062F \u00AB\u0628\u0627\u0646\u06A9 \u0627\u0645\u0646\u00BB \u0628\u0627\u0634\u0646\u062F \u06A9\u0647 \u067E\u0648\u0644 \u0633\u067E\u0631\u062F\u0647\u200C\u06AF\u0630\u0627\u0631\u0627\u0646 \u0631\u0627 \u0648\u0627\u0645 \u0646\u062F\u0647\u0646\u062F \u06CC\u0627 \u0633\u0631\u0645\u0627\u06CC\u0647\u200C\u06AF\u0630\u0627\u0631\u06CC \u0646\u06A9\u0646\u0646\u062F.", "bank_runs_safe_content_2": "\u0627\u0645\u0627 \u062F\u0631\u062E\u0648\u0627\u0633\u062A\u200C\u0647\u0627\u06CC\u0634\u0627\u0646 \u062A\u0648\u0633\u0637 \u0641\u062F\u0631\u0627\u0644 \u0631\u0632\u0631\u0648 \u0631\u062F \u0634\u062F\u0647 \u0627\u0633\u062A.", "bank_runs_safe_content_3": "\u0686\u0648\u0646 \u0627\u0632 \u0641\u0639\u0627\u0644\u06CC\u062A \u0645\u0646\u0639 \u0634\u062F\u0647\u200C\u0627\u0646\u062F\u060C \u0627\u0645\u0631\u0648\u0632 \u0647\u06CC\u0686 \u0628\u0627\u0646\u06A9\u06CC \u0628\u062F\u0648\u0646 \u0630\u062E\u06CC\u0631\u0647 \u06A9\u0633\u0631\u06CC \u0648\u062C\u0648\u062F \u0646\u062F\u0627\u0631\u062F.", "bank_runs_safe_content_4": "\u062E\u0648\u0634\u0628\u062E\u062A\u0627\u0646\u0647\u060C \u0631\u0627\u0647\u06CC \u0628\u0631\u0627\u06CC \u062E\u0631\u0648\u062C \u0627\u0632 \u0633\u06CC\u0633\u062A\u0645 \u0630\u062E\u06CC\u0631\u0647 \u06A9\u0633\u0631\u06CC \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F: \u0628\u0627\u0646\u06A9 \u062E\u0648\u062F\u062A\u0627\u0646 \u0628\u0627\u0634\u06CC\u062F.", "bank_runs_safe_content_5": "\u067E\u0633\u200C\u0627\u0646\u062F\u0627\u0632 \u0628\u0647 \u0635\u0648\u0631\u062A \u067E\u0648\u0644 \u0646\u0642\u062F \u0647\u0645\u0686\u0646\u0627\u0646 \u062F\u0631 \u0628\u0631\u0627\u0628\u0631 \u062A\u0648\u0631\u0645 \u0622\u0633\u06CC\u0628\u200C\u067E\u0630\u06CC\u0631 \u0627\u0633\u062A.", "bank_runs_safe_content_6": "\u0645\u0627 \u062F\u0631\u0628\u0627\u0631\u0647 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0635\u062D\u0628\u062A \u0645\u06CC\u200C\u06A9\u0646\u06CC\u0645: \u06CC\u06A9 \u0633\u06CC\u0633\u062A\u0645 \u0645\u0627\u0644\u06CC \u062C\u062F\u06CC\u062F \u06A9\u0647 \u0628\u0647 \u0634\u0645\u0627 \u0627\u0645\u06A9\u0627\u0646 \u0645\u06CC\u200C\u062F\u0647\u062F \u0628\u0627\u0646\u06A9 \u062E\u0648\u062F\u062A\u0627\u0646 \u0628\u0627\u0634\u06CC\u062F.",
	"bank_runs_protect": "\u0622\u06CC\u0627 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u0645\u0631\u0627 \u0627\u0632 \u0647\u062C\u0648\u0645 \u0628\u0627\u0646\u06A9\u06CC \u0645\u062D\u0627\u0641\u0638\u062A \u06A9\u0646\u062F\u061F", "bank_runs_protect_content_1": "\u0628\u0644\u0647\u060C \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u06CC\u06A9 \u0633\u06CC\u0633\u062A\u0645 \u0645\u0627\u0644\u06CC \u0628\u0627 \u0630\u062E\u06CC\u0631\u0647 \u06A9\u0627\u0645\u0644 \u0627\u0633\u062A.", "bank_runs_protect_content_2": "\u0647\u062C\u0648\u0645 \u0628\u0627\u0646\u06A9\u06CC \u062F\u0631 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u063A\u06CC\u0631\u0645\u0645\u06A9\u0646 \u0627\u0633\u062A \u062A\u0627 \u0632\u0645\u0627\u0646\u06CC \u06A9\u0647 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u062E\u0648\u062F \u0631\u0627 \u0628\u0647 \u06A9\u06CC\u0641 \u067E\u0648\u0644 \u062E\u0648\u062F\u062A\u0627\u0646 \u0628\u0631\u062F\u0627\u0634\u062A \u06A9\u0646\u06CC\u062F.", "bank_runs_protect_content_3": "\u0631\u0627\u0647\u0646\u0645\u0627\u06CC \u0633\u0627\u062F\u0647 \u06A9\u06CC\u0641 \u067E\u0648\u0644 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0645\u0627 \u0631\u0627 \u0628\u0628\u06CC\u0646\u06CC\u062F.", "bank_runs_protect_content_4": "\u0628\u0627 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646\u060C \u0628\u0627\u0644\u0627\u062E\u0631\u0647 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u06A9\u0646\u062A\u0631\u0644 \u067E\u0648\u0644\u062A\u0627\u0646 \u0631\u0627 \u062F\u0631 \u062F\u0633\u062A \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u06CC\u062F."
});

