	"placeholder_name_optional": "\u0646\u0627\u0645 (\u0627\u062E\u062A\u06CC\u0627\u0631\u06CC)", "placeholder_address_line_1": "\u0622\u062F\u0631\u0633 \u062E\u0637 \u06F1", "placeholder_address_line_2": "\u0622\u062F\u0631\u0633 \u062E\u0637 \u06F2 (\u0627\u062E\u062A\u06CC\u0627\u0631\u06CC)", "placeholder_city": "\u0634\u0647\u0631", "placeholder_state": "\u0627\u06CC\u0627\u0644\u062A", "placeholder_province": "\u0627\u0633\u062A\u0627\u0646", "placeholder_zip_code": "\u06A9\u062F \u067E\u0633\u062A\u06CC", "placeholder_postal_code": "\u06A9\u062F \u067E\u0633\u062A\u06CC", "placeholder_language": "\u0632\u0628\u0627\u0646", "placeholder_which_stickers": "\u06A9\u062F\u0627\u0645 \u0628\u0631\u0686\u0633\u0628\u200C\u0647\u0627\u061F", "placeholder_email_optional": "\u0627\u06CC\u0645\u06CC\u0644 \u0628\u0631\u0627\u06CC \u0627\u0637\u0644\u0627\u0639\u200C\u0631\u0633\u0627\u0646\u06CC (\u0627\u062E\u062A\u06CC\u0627\u0631\u06CC)"
