	"flyers_intro_c1": "\u0645\u0623\u0645\u0648\u0631\u06CC\u062A \u0645\u0627 \u06A9\u0645\u06A9 \u0628\u0647 \u0634\u0645\u0627\u0633\u062A \u062A\u0627 \u0628\u0627 \u0646\u0635\u0628 \u0628\u0631\u0648\u0634\u0648\u0631\u0647\u0627\u06CC \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u062F\u0631 \u0627\u0645\u0627\u06A9\u0646 \u0639\u0645\u0648\u0645\u06CC \u0627\u0641\u0631\u0627\u062F \u0628\u06CC\u0634\u062A\u0631\u06CC \u0631\u0627 \u0622\u0634\u0646\u0627 \u06A9\u0646\u06CC\u062F. \u0627\u06CC\u0646 \u0628\u0631\u0648\u0634\u0648\u0631 \u06A9\u062F QR \u062F\u0627\u0631\u062F \u06A9\u0647 \u0628\u0647", "flyers_intro_c2": "\u0648\u0628\u200C\u0633\u0627\u06CC\u062A \u0622\u0645\u0648\u0632\u0634\u06CC \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0645\u0627 \u0644\u06CC\u0646\u06A9 \u0645\u06CC\u200C\u062F\u0647\u062F.", "flyers_intro_c3": "\u062A\u0648\u0631\u0645",
	"flyers_intro_c4": "\u0627\u06CC\u0646 \u0628\u0631\u0648\u0634\u0648\u0631 \u0631\u0627 \u062F\u0631 \u062E\u0627\u0646\u0647 \u06CC\u0627 \u0686\u0627\u067E\u062E\u0627\u0646\u0647 \u0686\u0627\u067E \u06A9\u0646\u06CC\u062F. \u0633\u067E\u0633 \u0631\u0648\u06CC \u062A\u0627\u0628\u0644\u0648\u0647\u0627\u06CC \u0627\u0639\u0644\u0627\u0646\u0627\u062A\u060C \u062A\u06CC\u0631\u0647\u0627\u06CC \u062A\u0644\u0641\u0646 \u0648 \u0641\u0636\u0627\u0647\u0627\u06CC \u0639\u0645\u0648\u0645\u06CC \u0646\u0635\u0628 \u06A9\u0646\u06CC\u062F.", "flyers_intro_c5": "\u062F\u0631 \u0647\u0645\u06CC\u0646 \u062D\u06CC\u0646\u060C \u06CC\u06A9 \u0628\u0633\u062A\u0647 \u0627\u0632", "flyers_intro_c6": "\u0628\u0631\u0686\u0633\u0628\u200C\u0647\u0627\u06CC \u0631\u0627\u06CC\u06AF\u0627\u0646 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646", "flyers_intro_c7": "\u062F\u0631\u062E\u0648\u0627\u0633\u062A \u06A9\u0646\u06CC\u062F.",
	"flyers_btn_download": "\u062F\u0627\u0646\u0644\u0648\u062F \u0628\u0631\u0648\u0634\u0648\u0631", "flyers_btn_print": "\u0686\u0627\u067E \u0628\u0631\u0648\u0634\u0648\u0631", "flyers_share_header": "\u0645\u06A9\u0627\u0646\u200C\u0647\u0627\u06CC \u0628\u0631\u0648\u0634\u0648\u0631 \u062E\u0648\u062F \u0631\u0627 \u0628\u0647 \u0627\u0634\u062A\u0631\u0627\u06A9 \u0628\u06AF\u0630\u0627\u0631\u06CC\u062F", "flyers_share_c1": "\u0645\u06A9\u0627\u0646\u200C\u0647\u0627\u06CC \u0628\u0631\u0648\u0634\u0648\u0631 \u062E\u0648\u062F \u0631\u0627 \u0628\u0627 \u0645\u0627 \u062F\u0631 Nostr \u0628\u0647 \u0627\u0634\u062A\u0631\u0627\u06A9 \u0628\u06AF\u0630\u0627\u0631\u06CC\u062F.", "flyers_btn_share_on_nostr": "\u0627\u0634\u062A\u0631\u0627\u06A9 \u062F\u0631 NOSTR", "flyers_btn_what_is_nostr": "NOSTR \u0686\u06CC\u0633\u062A\u061F"
