	"get_involved_request_a": "\u062F\u0631\u062E\u0648\u0627\u0633\u062A \u06CC\u06A9", "get_involved_sticker_pack": "\u0628\u0633\u062A\u0647 \u0628\u0631\u0686\u0633\u0628",
	"get_involved_postcard_header": "\u06CC\u06A9 \u06A9\u0627\u0631\u062A\u200C\u067E\u0633\u062A\u0627\u0644 \u0628\u0641\u0631\u0633\u062A\u06CC\u062F", "get_involved_postcard_content_1": "\u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u0628\u0627 \u0627\u0631\u0633\u0627\u0644 \u06CC\u06A9\u06CC \u0627\u0632 \u06A9\u0627\u0631\u062A\u200C\u067E\u0633\u062A\u0627\u0644\u200C\u0647\u0627\u06CC \u0631\u0627\u06CC\u06AF\u0627\u0646 \u0645\u0627 \u0627\u0645\u06CC\u062F \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0631\u0627 \u06AF\u0633\u062A\u0631\u0634 \u062F\u0647\u06CC\u062F.", "get_involved_postcard_content_2": "\u067E\u0634\u062A \u0647\u0631 \u06A9\u0627\u0631\u062A\u200C\u067E\u0633\u062A\u0627\u0644 \u0645\u062A\u0646\u06CC \u062C\u0630\u0627\u0628 \u062F\u0631\u0628\u0627\u0631\u0647 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0628\u0627 \u06A9\u062F QR \u062F\u0627\u0631\u062F.", "get_involved_postcard_content_3": "\u0628\u0627 \u0627\u0631\u0633\u0627\u0644 \u06CC\u06A9 \u06A9\u0627\u0631\u062A\u200C\u067E\u0633\u062A\u0627\u0644 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646\u060C \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u062F\u06CC\u062F \u062C\u062F\u06CC\u062F\u06CC \u0627\u0632 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0628\u0647 \u06A9\u0633\u06CC \u0628\u062F\u0647\u06CC\u062F.", "get_involved_postcard_pack": "\u0628\u0633\u062A\u0647 \u06A9\u0627\u0631\u062A\u200C\u067E\u0633\u062A\u0627\u0644",
	"get_involved_business_header": "\u06CC\u06A9 \u06A9\u0633\u0628\u200C\u0648\u06A9\u0627\u0631 \u0631\u0627 \u0622\u0646\u0628\u0648\u0631\u062F \u06A9\u0646\u06CC\u062F", "get_involved_business_content_1": "\u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u06CC\u062F \u0628\u0647 \u0633\u0627\u062E\u062A\u0646 \u0627\u0642\u062A\u0635\u0627\u062F \u062F\u0627\u06CC\u0631\u0647\u200C\u0627\u06CC \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u06A9\u0645\u06A9 \u06A9\u0646\u06CC\u062F\u061F", "get_involved_business_content_2": "\u0647\u0631 \u0628\u0633\u062A\u0647 \u06A9\u0633\u0628\u200C\u0648\u06A9\u0627\u0631 \u0634\u0627\u0645\u0644 \u0628\u0631\u0648\u0634\u0648\u0631\u0647\u0627\u06CC\u06CC \u0627\u0633\u062A \u06A9\u0647 \u0645\u0632\u0627\u06CC\u0627\u06CC \u067E\u0630\u06CC\u0631\u0634 \u067E\u0631\u062F\u0627\u062E\u062A \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0631\u0627 \u0646\u0634\u0627\u0646 \u0645\u06CC\u200C\u062F\u0647\u062F. \u0647\u0631 \u0628\u0631\u0648\u0634\u0648\u0631 \u0628\u0647 \u0627\u0646\u0648\u0627\u0639", "get_involved_business_content_3": "\u0645\u0646\u0627\u0628\u0639 \u0631\u0627\u06CC\u06AF\u0627\u0646 \u06A9\u0633\u0628\u200C\u0648\u06A9\u0627\u0631 \u0628\u06CC\u062A\u200C\u06A9\u0648\u06CC\u0646 \u0644\u06CC\u0646\u06A9 \u0645\u06CC\u200C\u062F\u0647\u062F.", "get_involved_business_kit": "\u0628\u0633\u062A\u0647 \u06A9\u0633\u0628\u200C\u0648\u06A9\u0627\u0631"
